@code {
    [Parameter, EditorRequired] public List<WorkEntry> Entries { get; set; } = [];
    [Parameter] public EventCallback<List<WorkEntry>> OnEntriesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void HandleEntryChanged(int index, WorkEntry updated)
    {
        var list = new List<WorkEntry>(Entries);
        list[index] = updated;
        OnEntriesChanged.InvokeAsync(list);
    }

    private void HandleRemove(int index)
    {
        var list = new List<WorkEntry>(Entries);
        list.RemoveAt(index);
        OnEntriesChanged.InvokeAsync(list);
    }

    private void AddEntry()
    {
        var list = new List<WorkEntry>(Entries)
        {
