{"file_text": "@* Step 3 — References *@

<h4 class="mb-3">References</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <ReferenceForm Reference="@References[index]"
                   Index="index"
                   CanRemove="@(References.Count > 2)"
                   OnChanged="e => HandleReferenceChanged(index, e)"
                   OnRemove="() => HandleRemove(index)" />
}

@if (References.Count < 3)
{
    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<Reference> References { get; set; } = [];
    [Parameter] public EventCallback<List<Reference>> OnReferencesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void HandleReferenceChanged(int index, Reference updated)
    {
        var list = new List<Reference>(References);
        list[index] = updated;
        OnReferencesChanged.InvokeAsync(list);
    }

    private void HandleRemove(int index)
    {
        var list = new List<Reference>(References);
        list.RemoveAt(index);
        OnReferencesChanged.InvokeAsync(list);
    }

    private void AddReference()
    {
        if (References.Count >= 3) return;
        var list = new List<Reference>(References)
        {
            new(string.Empty, string.Empty, string.Empty, string.Empty)
        };
        OnReferencesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        if (References.Count < 2)
        {
            ErrorMessage = "Please provide at least 2 references.";
            return;
        }
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference must have a name and email.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }
}
