@page "/apply"
@using sv_6a92e697c52f42908454d5731cc4211c.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    <StepIndicator CurrentStep="currentStep"
                   StepNames="stepNames"
                   OnStepClicked="GoToStep" />

    <div class="mt-4">
        @switch (currentStep)
        {
            case 0:
                <PersonalInfoStep Model="personalInfo"
                                  ApplicationService="ApplicationService"
                                  OnModelChanged="p => personalInfo = p"
                                  OnNext="NextStep" />
                break;
            case 1:
                <WorkHistoryStep Entries="workEntries"
                                 OnEntriesChanged="e => workEntries = e"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 2:
                <ReferencesStep References="references"
                                OnReferencesChanged="r => references = r"
                                OnNext="NextStep"
                                OnBack="PreviousStep" />
                break;
            case 3:
                <CoverLetterStep CoverLetter="coverLetter"
                                 OnCoverLetterChanged="c => coverLetter = c"
                                 OnNext="NextStep"
                                 OnBack="PreviousStep" />
                break;
            case 4:
                <ReviewStep Personal="personalInfo"
                            WorkEntries="workEntries"
                            References="references"
                            CoverLetter="coverLetter"
                            IsSubmitted="isSubmitted"
                            ApplicationId="applicationId"
                            OnEditSection="GoToStep"
                            OnBack="PreviousStep"
                            OnSubmit="SubmitApplication" />
                break;
        }
    </div>
</div>

@code {
    private static readonly IReadOnlyList<string> stepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int currentStep;
    private PersonalInfo personalInfo = new(string.Empty, string.Empty, string.Empty, string.Empty);
    private List<WorkEntry> workEntries = [new(string.Empty, string.Empty, DateTime.Today, null, string.Empty)];
    private List<Reference> references =
    [
        new(string.Empty, string.Empty, string.Empty, string.Empty),
        new(string.Empty, string.Empty, string.Empty, string.Empty)
    ];
    private string coverLetter = string.Empty;
    private bool isSubmitted;
    private int? applicationId;

    private void NextStep() => currentStep = Math.Min(currentStep + 1, stepNames.Count - 1);
    private void PreviousStep() => currentStep = Math.Max(currentStep - 1, 0);

    private void GoToStep(int step)
    {
        if (step < currentStep)
            currentStep = step;
    }

    private async Task SubmitApplication()
    {
        var application = new JobApplication(
            personalInfo,
            new WorkHistory(workEntries),
            references,
            coverLetter);

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitted = true;
    }
}

